<template>
  <div class="container">
    <main class="content-wrapper">
      <!-- Video section -->
      <section class="card video-section">
        <div class="card-header" style="display: flex; justify-content: center; align-items: center; height: 80px;">
          <h2>Video Frame Processing (5 FPS)</h2>
        </div>
        <div class="card-body">
          <div class="video-container">
            <!-- Video upload upload -->
            <div class="video-upload">
              <label class="file-label" @click="resetVideo">
                <i class="fas fa-video file-icon"></i>
                <p class="file-text">
                  {{ selectedVideoName || 'Click to select a video file (MP4, WebM)' }}
                </p>
                <input 
                  type="file" 
                  class="file-input" 
                  accept="video/*" 
                  @change="handleVideoUpload"
                  ref="fileInputRef"
                >
              </label>
            </div>
            
            <!-- Processing mode selection -->
            <div class="processing-mode-selector" v-if="isVideoLoaded">
              <button 
                class="mode-btn" 
                :class="{ active: processingMode === 'realtime' }"
                @click="setProcessingMode('realtime')"
              >
                <i class="fas fa-play-circle"></i> Real-time Processing
              </button>
              <button 
                class="mode-btn" 
                :class="{ active: processingMode === 'framebyframe' }"
                @click="setProcessingMode('framebyframe')"
              >
                <i class="fas fa-film"></i> Frame-by-Frame Processing (5 FPS)
              </button>
            </div>
            
            <!-- Frame processing progress -->
            <div v-if="processingMode === 'framebyframe' && isProcessingFrames">
              <div class="processing-progress">
                <div class="progress-bar" :style="{ width: frameProcessingProgress + '%' }"></div>
              </div>
              <p class="progress-text">
                Processing frame {{ currentFrame }} of {{ totalFrames }} ({{ frameProcessingProgress.toFixed(1) }}%)
                <span v-if="processingSpeed">| Speed: {{ processingSpeed.toFixed(1) }} fps</span>
              </p>
            </div>
            
            <!-- Video player with detection overlay -->
            <div v-show="isVideoLoaded" class="camera-preview-wrapper">
              <video 
                id="videoPlayer" 
                class="camera-preview" 
                playsinline
                ref="videoRef"
                @ended="handleVideoEnded"
                :controls="processingMode === 'realtime'"
              ></video>
              <canvas 
                id="detectionCanvas" 
                class="detection-canvas"
                ref="canvasRef"
              ></canvas>
            </div>
            
            <!-- Video control buttons -->
            <div class="camera-controls">
              <button 
                class="btn btn-primary start-camera-btn" 
                @click="startVideo"
                :disabled="!isVideoLoaded || isVideoPlaying || isLoading || processingMode === 'framebyframe'"
              >
                <i class="fas fa-play"></i> Play Video
              </button>
              <button 
                class="btn btn-danger stop-camera-btn" 
                @click="pauseVideo"
                :disabled="!isVideoPlaying || processingMode === 'framebyframe'"
              >
                <i class="fas fa-pause"></i> Pause Video
              </button>
              <button 
                class="btn btn-secondary toggle-detection-btn" 
                @click="toggleDetection"
                :disabled="!isVideoLoaded || processingMode === 'framebyframe'"
              >
                <i v-if="isDetecting" class="fas fa-pause"></i>
                <i v-if="!isDetecting" class="fas fa-play"></i>
                {{ isDetecting ? 'Pause Detection' : 'Start Detection' }}
              </button>
              
              <!-- Frame processing button -->
              <button 
                class="btn btn-success process-frames-btn" 
                @click="processAllFrames"
                :disabled="!isVideoLoaded || isProcessingFrames || processingMode !== 'framebyframe'"
              >
                <i v-if="!isProcessingFrames" class="fas fa-cog"></i>
                <i v-if="isProcessingFrames" class="fas fa-spinner fa-spin"></i>
                {{ isProcessingFrames ? 'Processing...' : 'Process All Frames' }}
              </button>
              
              <!-- Export buttons -->
              <button 
                @click="exportToXLS()" 
                class="btn btn-primary upload-btn"
                :disabled="!isVideoLoaded || allDetections.length === 0 || isExporting"
              >
                <span v-if="!isExporting">
                  <i class="fas fa-file-excel"></i> Export Results
                </span>
                <span v-if="isExporting">
                  <i class="fas fa-spinner fa-spin"></i> Exporting...
                </span>
              </button>
              
              <!-- Export processed video button -->
              <button 
                @click="exportProcessedVideo()" 
                class="btn btn-info export-video-btn"
                :disabled="!isVideoLoaded || !hasProcessedFrames || isExportingVideo || processingMode !== 'framebyframe'"
              >
                <span v-if="!isExportingVideo">
                  <i class="fas fa-video"></i> Export Video
                </span>
                <span v-if="isExportingVideo">
                  <i class="fas fa-spinner fa-spin"></i> Exporting...
                </span>
              </button>
            </div>
          </div>
        </div>
      </section>

      <!-- Results section -->
      <section class="card results-section">
       <div class="card-header" style="display: flex; justify-content: center; align-items: center; height: 80px;">
          <h2>Video Detection Results</h2>
       </div>
        <div class="card-body">
          <div id="detectionResults" class="results-content">
            <!-- Loading state -->
            <div v-if="isLoading || isProcessingFrames" class="status-indicator loading">
              <i class="fas fa-circle-notch fa-spin"></i>
              <p>{{ isProcessingFrames ? 'Processing all frames, please wait...' : 'Detecting, please wait...' }}</p>
            </div>
            
            <!-- Error message -->
            <div v-if="errorMessage" class="status-indicator error">
              <i class="fas fa-exclamation-circle"></i>
              <p>{{ errorMessage }}</p>
            </div>
            
            <!-- Detection results -->
            <div v-if="detections.length > 0 && !isLoading && !isProcessingFrames && !errorMessage" class="detections-list">
              <p class="results-summary">
                Current: {{ detections.length }} objects | 
                Total recorded: <span class="count">{{ allDetections.length }}</span>
              </p>
              <ul>
                <li v-for="(obj, index) in detections" :key="index" class="detection-item">
                  <div class="detection-class">{{ obj.class }}</div>
                  <div class="detection-meta">
                    <span class="confidence">Confidence: {{ obj.confidence.toFixed(2) }}</span>
                    <span class="position">Position: {{ formatBox(obj.box) }}</span>
                  </div>
                </li>
              </ul>
            </div>

            <!-- No video selected prompt -->
            <div v-if="!isVideoLoaded && !isLoading && !isProcessingFrames && !errorMessage && detections.length === 0" class="status-indicator info">
              <i class="fas fa-info-circle"></i>
              <p>Please select a video file to begin detection</p>
            </div>
          </div>
        </div>
      </section>
    </main>

    <footer class="page-footer">
      <p>Video Detection System &copy; 2025</p>
    </footer>
  </div>
</template>

<script setup>
import { ref, onMounted,onUnmounted, nextTick, watch } from 'vue';
const isProcessingFrames = ref(false);
// 调试函数 - 带时间戳的日志输出
const debugLog = (message, data = null) => {
  const timestamp = new Date().toISOString().split('T')[1];
  console.log(`[${timestamp}] ${message}`, data ? data : '');
};

// 定期输出按钮状态的调试函数
const logButtonStates = () => {
  const buttonStates = {
    "Play Video": {
      disabled: !isVideoLoaded.value || isVideoPlaying.value || isLoading.value || processingMode.value === 'framebyframe',
      conditions: {
        "!isVideoLoaded": !isVideoLoaded.value,
        "isVideoPlaying": isVideoPlaying.value,
        "isLoading": isLoading.value,
        "processingMode === 'framebyframe'": processingMode.value === 'framebyframe'
      }
    },
    "Pause Video": {
      disabled: !isVideoPlaying.value || processingMode.value === 'framebyframe',
      conditions: {
        "!isVideoPlaying": !isVideoPlaying.value,
        "processingMode === 'framebyframe'": processingMode.value === 'framebyframe'
      }
    },
    "Start/Pause Detection": {
      disabled: !isVideoLoaded.value || processingMode.value === 'framebyframe',
      conditions: {
        "!isVideoLoaded": !isVideoLoaded.value,
        "processingMode === 'framebyframe'": processingMode.value === 'framebyframe'
      }
    },
    "Process All Frames": {
      disabled: !isVideoLoaded.value || isProcessingFrames.value || processingMode.value !== 'framebyframe',
      conditions: {
        "!isVideoLoaded": !isVideoLoaded.value,
        "isProcessingFrames": isProcessingFrames.value,
        "processingMode !== 'framebyframe'": processingMode.value !== 'framebyframe'
      }
    },
    "Export Results": {
      disabled: !isVideoLoaded.value || allDetections.value.length === 0 || isExporting.value,
      conditions: {
        "!isVideoLoaded": !isVideoLoaded.value,
        "allDetections.length === 0": allDetections.value.length === 0,
        "isExporting": isExporting.value
      }
    },
    "Export Video": {
      disabled: !isVideoLoaded.value || !hasProcessedFrames.value || isExportingVideo.value || processingMode.value !== 'framebyframe',
      conditions: {
        "!isVideoLoaded": !isVideoLoaded.value,
        "!hasProcessedFrames": !hasProcessedFrames.value,
        "isExportingVideo": isExportingVideo.value,
        "processingMode !== 'framebyframe'": processingMode.value !== 'framebyframe'
      }
    }
  };
  
  debugLog("当前按钮状态:", buttonStates);
};

// 每2秒输出一次状态，帮助追踪变化
setInterval(() => {
  debugLog("=== 状态检查 ===");
  debugLog("核心状态:", {
    isVideoLoaded: isVideoLoaded.value,
    isVideoPlaying: isVideoPlaying.value,
    isDetecting: isDetecting.value,
    isProcessingFrames: isProcessingFrames.value,
    processingMode: processingMode.value,
    allDetectionsCount: allDetections.value.length,
    hasProcessedFrames: hasProcessedFrames.value
  });
  logButtonStates();
}, 2000);

// Video related states
const videoRef = ref(null);
const canvasRef = ref(null);
const fileInputRef = ref(null);
const selectedVideoName = ref('');
const isVideoLoaded = ref(false);
const isVideoPlaying = ref(false);
const isDetecting = ref(false);
const detectionInterval = ref(null);
const videoSource = ref(null);
const detectionStartTime = ref(null);
const processingMode = ref('realtime'); // 'realtime' or 'framebyframe'

// 监听核心状态变化并输出日志
watch([isVideoLoaded, isVideoPlaying, isDetecting, isProcessingFrames, processingMode], 
  ([newLoaded, newPlaying, newDetecting, newProcessing, newMode], 
   [oldLoaded, oldPlaying, oldDetecting, oldProcessing, oldMode]) => {
  debugLog("核心状态变化:", {
    isVideoLoaded: { from: oldLoaded, to: newLoaded },
    isVideoPlaying: { from: oldPlaying, to: newPlaying },
    isDetecting: { from: oldDetecting, to: newDetecting },
    isProcessingFrames: { from: oldProcessing, to: newProcessing },
    processingMode: { from: oldMode, to: newMode }
  });
  logButtonStates();
});

// Frame processing states - 关键修改：设置为1秒5帧

const totalFrames = ref(0);
const currentFrame = ref(0);
const frameProcessingProgress = ref(0);
const processedFrames = ref([]); // 存储处理后的帧
const hasProcessedFrames = ref(false);
const frameInterval = ref(200); // 1秒5帧 = 每200毫秒1帧 (1000ms / 5 = 200ms)
const processingSpeed = ref(0); // 处理速度（每秒帧数）

// Export video states
const isExportingVideo = ref(false);
const videoEncoder = ref(null);
const videoChunks = ref([]);

// Detection results
const detections = ref([]); // 当前帧检测结果
const allDetections = ref([]); // 所有检测结果
const isLoading = ref(false);
const errorMessage = ref('');
const isExporting = ref(false);

// Load SheetJS library dynamically
const loadSheetJS = async () => {
  debugLog("开始加载SheetJS库");
  if (window.XLSX) {
    debugLog("SheetJS库已加载");
    return Promise.resolve(window.XLSX);
  }
  
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
    script.onload = () => {
      debugLog("SheetJS库加载成功");
      resolve(window.XLSX);
    };
    script.onerror = (err) => {
      debugLog("SheetJS库加载失败", err);
      reject(err);
    };
    document.head.appendChild(script);
  });
};

// 修改Set processing mode方法
const setProcessingMode = (mode) => {
  // 只有当模式真正改变时才执行操作
  if (processingMode.value === mode) {
    debugLog(`已处于${mode}模式，无需切换`);
    return;
  }
  
  debugLog(`切换处理模式: ${processingMode.value} -> ${mode}`);
  
  // 停止检测和播放
  toggleDetection(false);
  pauseVideo();
  
  // 根据模式类型决定重置程度
  if (processingMode.value === 'realtime' && mode === 'framebyframe' && isVideoLoaded.value) {
    debugLog("从实时模式切换到帧模式，保持视频加载状态");
    // 仅重置与检测相关的状态，不清除视频源
    detections.value = [];
    allDetections.value = [];
    processedFrames.value = [];
    hasProcessedFrames.value = false;
    currentFrame.value = 0;
    frameProcessingProgress.value = 0;
  } else {
    // 其他情况执行完全重置
    resetVideo();
  }
  
  processingMode.value = mode;
  debugLog(`处理模式已切换为: ${mode}`);
  
  // 如果切换到帧模式且视频已加载，重新设置视频到开始位置
  if (mode === 'framebyframe' && isVideoLoaded.value && videoRef.value) {
    videoRef.value.currentTime = 0;
  }
};


// Handle video file upload
const handleVideoUpload = (event) => {
  debugLog("触发视频上传处理");
  const file = event.target.files[0];
  if (!file) {
    debugLog("未选择视频文件");
    return;
  }
  
  // 验证文件类型
  if (!file.type.startsWith('video/')) {
    errorMessage.value = "请选择有效的视频文件";
    debugLog("选择的不是视频文件");
    // 清空文件输入，允许重新选择
    if (fileInputRef.value) {
      fileInputRef.value.value = '';
    }
    return;
  }
  
  debugLog(`选中视频文件: ${file.name}, 大小: ${(file.size / (1024 * 1024)).toFixed(2)}MB, 类型: ${file.type}`);
  
  // 重置之前的状态，但保留视频元素
  resetVideo(false); // 传递参数表示不完全重置DOM元素
  
  // 设置显示的视频名称
  selectedVideoName.value = file.name;
  
  // 创建视频源URL
  try {
    videoSource.value = URL.createObjectURL(file);
    debugLog("已创建视频源URL");
  } catch (err) {
    errorMessage.value = "创建视频源失败，请重试";
    debugLog("创建视频源URL时出错:", err);
    return;
  }
  
  // 改进的视频初始化逻辑
  const initVideo = (retryCount = 0) => {
    // 强制获取视频元素，优先使用ref的方式
    const videoElement = videoRef.value || document.getElementById('videoPlayer');
    if (!videoElement) {
      debugLog(`videoRef仍不存在在，重试次数: ${retryCount}`);
      // 增加重试次数到10次，提高成功率
      if (retryCount < 10) {
        setTimeout(() => initVideo(retryCount + 1), 100);
      } else {
        errorMessage.value = "无法初始化视频播放器，请检查页面结构或刷新页面";
        debugLog("超过最大重试次数，无法初始化视频");
        // 清理资源
        if (videoSource.value) {
          URL.revokeObjectURL(videoSource.value);
          videoSource.value = null;
        }
      }
      return;
    }
    
    // 将获取到的元素赋值给ref（如果尚未赋值）
    if (!videoRef.value) {
      videoRef.value = videoElement;
      debugLog("通过ID获取视频元素并绑定到ref");
    }
    
    debugLog("开始初始化视频元素");
    
    // 确保清除之前的事件监听器
    videoRef.value.removeEventListener('loadedmetadata', onMetadataLoaded);
    videoRef.value.removeEventListener('error', onVideoError);
    
    // 定义元数据加载完成处理函数
    function onMetadataLoaded() {
      debugLog(`视频元数据加载完成: 时长 ${videoRef.value.duration.toFixed(2)}秒, 尺寸 ${videoRef.value.videoWidth}x${videoRef.value.videoHeight}`);
      
      if (canvasRef.value) {
        canvasRef.value.width = videoRef.value.videoWidth;
        canvasRef.value.height = videoRef.value.videoHeight;
        debugLog(`Canvas已初始化: 尺寸 ${canvasRef.value.width}x${canvasRef.value.height}`);
      }
      
      // 计算总帧数：视频时长(秒) × 5帧/秒
      totalFrames.value = Math.ceil(videoRef.value.duration * 5);
      isVideoLoaded.value = true;
      errorMessage.value = '';
      debugLog(`视频加载完成，总帧数: ${totalFrames.value}`);
      
      // 视频加载成功后，重置文件输入，允许选择新文件
      if (fileInputRef.value) {
        fileInputRef.value.value = '';
      }
    }
    
    // 定义视频错误处理函数
    function onVideoError(err) {
      const errorMsg = `视频加载错误: ${err.message || '未知错误'}`;
      debugLog("视频加载错误", err);
      errorMessage.value = errorMsg;
      isVideoLoaded.value = false;
      
      // 清理资源
      if (videoSource.value) {
        URL.revokeObjectURL(videoSource.value);
        videoSource.value = null;
      }
    }
    
    // 添加事件监听器
    videoRef.value.addEventListener('loadedmetadata', onMetadataLoaded);
    videoRef.value.addEventListener('error', onVideoError);
    
    // 设置视频源
    videoRef.value.src = videoSource.value;
  };
  
  // 使用nextTick确保DOM已更新
  nextTick(() => {
    initVideo(0);
  });
};


// Start playing video
const startVideo = () => {
  debugLog("尝试播放视频");
  if (!videoRef.value || !isVideoLoaded.value) {
    debugLog("无法播放视频: videoRef不存在或视频未加载");
    return;
  }
  
  videoRef.value.play()
    .then(() => {
      debugLog("视频播放成功");
      isVideoPlaying.value = true;
      // Start detection automatically if it was active
      if (isDetecting.value && !detectionInterval.value) {
        debugLog("自动开始检测，因为检测状态为激活");
        detectFromVideo();
        detectionInterval.value = setInterval(detectFromVideo, 2000);
      }
    })
    .catch(err => {
      const errorMsg = `Error playing video: ${err.message}`;
      debugLog("视频播放失败", err);
      errorMessage.value = errorMsg;
    });
};

// Pause video
const pauseVideo = () => {
  debugLog("尝试暂停视频");
  if (!videoRef.value || !isVideoPlaying.value) {
    debugLog("无法暂停视频: videoRef不存在或视频未在播放");
    return;
  }
  
  videoRef.value.pause();
  isVideoPlaying.value = false;
  debugLog("视频已暂停");
};

// Handle video end
const handleVideoEnded = () => {
  debugLog("视频播放结束");
  isVideoPlaying.value = false;
  // Pause detection when video ends
  if (isDetecting.value) {
    debugLog("视频结束，自动暂停检测");
    toggleDetection(false);
  }
};

// Toggle detection
const toggleDetection = (forceState = null) => {
  const newState = forceState !== null ? forceState : !isDetecting.value;
  debugLog(`切换检测状态: ${isDetecting.value} -> ${newState}`);
  
  if (newState && !isDetecting.value) {
    // Start detection
    detectionStartTime.value = new Date();
    allDetections.value = [];
    isDetecting.value = true;
    debugLog("检测已启动");
    
    // Start detection loop if video is playing
    if (isVideoPlaying.value) {
      debugLog("视频正在播放，开始检测循环");
      detectFromVideo();
      detectionInterval.value = setInterval(detectFromVideo, 2000);
    } else {
      debugLog("视频未在播放，检测将在播放时自动开始");
    }
  } else if (!newState && isDetecting.value) {
    // Stop detection
    isDetecting.value = false;
    if (detectionInterval.value) {
      clearInterval(detectionInterval.value);
      detectionInterval.value = null;
      debugLog("检测循环已停止");
    }
    debugLog("检测已暂停");
  }
};

// Detect from video frame
const detectFromVideo = async () => {
  debugLog("开始从视频帧检测");
  if (!isVideoLoaded.value || !videoRef.value || !canvasRef.value || !isVideoPlaying.value) {
    debugLog("跳过检测: 视频未加载、videoRef不存在、canvasRef不存在或视频未在播放");
    return;
  }
  if (isLoading.value) {
    debugLog("跳过检测: 正在加载中");
    return;
  }

  try {
    isLoading.value = true;
    const ctx = canvasRef.value.getContext('2d');
    
    // Draw current video frame to canvas
    ctx.drawImage(videoRef.value, 0, 0, canvasRef.value.width, canvasRef.value.height);
    debugLog("已将当前视频帧绘制到canvas");
    
    // Convert canvas to blob for detection
    canvasRef.value.toBlob(async (blob) => {
      if (!blob) {
        debugLog("无法从canvas创建blob");
        isLoading.value = false;
        return;
      }
      
      debugLog(`创建帧blob: 大小 ${(blob.size / 1024).toFixed(2)}KB`);
      const formData = new FormData();
      formData.append('image', blob, 'video-frame.jpg');
      
      // Send frame to detection API
      debugLog("发送帧到检测API: https://fengguoheng.online/detect");
      const response = await fetch('https://fengguoheng.online/detect', { 
        method: 'POST', 
        body: formData 
      });
      
      if (!response.ok) {
        throw new Error(`API请求失败: ${response.status} ${response.statusText}`);
      }
      
      const data = await response.json();
      debugLog("从API接收检测结果", data);
      
      // Record current time as timestamp
      const detectionTime = new Date();
      const currentTime = videoRef.value.currentTime;
      
      // Update current frame detections
      detections.value = data.detections || [];
      debugLog(`检测到 ${detections.value.length} 个对象`);
      
      // Save all detections with timestamp and video time
      if (detections.value.length > 0) {
        const resultsWithTimestamp = detections.value.map(detection => ({
          ...detection,
          timestamp: detectionTime.toISOString(),
          videoTime: currentTime, // Video playback time in seconds
          frameNumber: allDetections.value.length + 1
        }));
        
        allDetections.value.push(...resultsWithTimestamp);
        debugLog(`已保存检测结果，总记录数: ${allDetections.value.length}`);
      }
      
      // Draw detection boxes
      drawDetectionBoxes(detections.value);
    }, 'image/jpeg');
  } catch (err) {
    const errorMsg = `Detection error: ${err.message}`;
    debugLog("检测错误", err);
    errorMessage.value = errorMsg;
  } finally {
    isLoading.value = false;
    debugLog("检测处理完成");
  }
};

// Process all frames sequentially (拆帧处理) - 关键修改：确保按顺序处理
// 修改帧处理和视频编码相关逻辑

// 1. 首先始化帧处理时的参数计算
// 1. 首先修改帧处理逻辑，记录每帧的时间戳
const processAllFrames = async () => {
  debugLog("开始处理所有帧");
  if (!isVideoLoaded.value || !videoRef.value || !canvasRef.value || isProcessingFrames.value) {
    debugLog("无法开始处理所有帧: 视频未加载、videoRef不存在、canvasRef不存在或正在处理中");
    return;
  }
  
  try {
    isProcessingFrames.value = true;
    currentFrame.value = 0;
    frameProcessingProgress.value = 0;
    allDetections.value = [];
    processedFrames.value = []; // 存储{dataUrl, timestamp}对象
    errorMessage.value = '';
    processingSpeed.value = 0;
    debugLog("初始化帧处理状态完成");
    
    const video = videoRef.value;
    const canvas = canvasRef.value;
    const ctx = canvas.getContext('2d');
    
    // 暂停视频并重置到开始位置
    video.pause();
    video.currentTime = 0;
    debugLog("视频已暂停并重置到开始位置");
    
    // 获取原视频信息
    const originalDuration = video.duration;
    const targetFps = 5;
    const totalFramesToProcess = Math.ceil(originalDuration * targetFps);
    const frameInterval = 1000 / targetFps; // 每帧应间隔的毫秒数
    totalFrames.value = totalFramesToProcess;
    debugLog(`原视频时长: ${originalDuration.toFixed(2)}秒, 目标帧率: ${targetFps}fps, 总帧数: ${totalFramesToProcess}`);
    
    // 处理每一帧并记录时间戳
    for (let i = 0; i < totalFramesToProcess; i++) {
      if (!isProcessingFrames.value) break;
      
      // 计算当前帧在原视频中的时间点（关键）
      const frameTimestamp = (i / targetFps); // 秒
      if (frameTimestamp > originalDuration) break;
      
      // 设置视频到正确时间点
      video.currentTime = frameTimestamp;
      
      // 等待视频定位完成
      await new Promise(resolve => {
        const checkSeeked = () => {
          if (Math.abs(video.currentTime - frameTimestamp) < 0.01) {
            video.removeEventListener('seeked', checkSeeked);
            resolve();
          }
        };
        video.addEventListener('seeked', checkSeeked);
      });
      
      // 绘制帧并检测
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const detections = await detectFrame(canvas, frameTimestamp, currentFrame.value + 1);
      drawDetectionBoxes(detections);
      
      // 存储帧数据和对应的时间戳（关键修改）
      processedFrames.value.push({
        dataUrl: canvas.toDataURL('image/png'),
        timestamp: frameTimestamp // 记录该帧在原视频中的时间点
      });
      
      // 更新进度
      currentFrame.value++;
      frameProcessingProgress.value = (currentFrame.value / totalFramesToProcess) * 100;
    }
    
    hasProcessedFrames.value = true;
    debugLog(`帧处理完成，共处理 ${processedFrames.value.length} 帧`);
    
  } catch (err) {
    const errorMsg = `Frame processing error: ${err.message}`;
    debugLog("帧处理错误", err);
    errorMessage.value = errorMsg;
  } finally {
    isProcessingFrames.value = false;
    processingSpeed.value = 0;
  }
};

// Detect objects in a single frame - 确保等待后端返回结果
const detectFrame = async (canvas, videoTime, frameNumber) => {
  debugLog(`开始检测第 ${frameNumber} 帧 (视频时间: ${videoTime.toFixed(2)}s)`);
  return new Promise((resolve) => {
    canvas.toBlob(async (blob) => {
      if (!blob) {
        debugLog(`第 ${frameNumber} 帧无法创建blob`);
        resolve([]);
        return;
      }
      
      try {
        const formData = new FormData();
        formData.append('image', blob, `frame-${frameNumber}.jpg`);
        debugLog(`第 ${frameNumber} 帧: 发送检测请求，blob大小 ${(blob.size / 1024).toFixed(2)}KB`);
        
        // 发送帧到后端并等待响应
        const response = await fetch('https://fengguoheng.online/detect', { 
          method: 'POST', 
          body: formData 
        });
        
        if (!response.ok) {
          throw new Error(`API请求失败: ${response.status} ${response.statusText}`);
        }
        
        const data = await response.json();
        const frameDetections = data.detections || [];
        debugLog(`第 ${frameNumber} 帧检测完成，发现 ${frameDetections.length} 个对象`);
        
        // 保存检测结果
        if (frameDetections.length > 0) {
          const resultsWithTimestamp = frameDetections.map(detection => ({
            ...detection,
            timestamp: new Date().toISOString(),
            videoTime: videoTime,
            frameNumber: frameNumber
          }));
          
          allDetections.value.push(...resultsWithTimestamp);
          debugLog(`第 ${frameNumber} 帧: 已保存检测结果，总记录数: ${allDetections.value.length}`);
        }
        
        resolve(frameDetections);
      } catch (err) {
        debugLog(`第 ${frameNumber} 帧检测错误`, err);
        resolve([]);
      }
    }, 'image/jpeg');
  });
};

// Draw detection boxes on canvas
const drawDetectionBoxes = (detections) => {
  if (!canvasRef.value || !videoRef.value) {
    debugLog("无法绘制检测框: canvasRef或videoRef不存在");
    return;
  }
  
  const ctx = canvasRef.value.getContext('2d');
  // 清除之前的绘制并重新绘制视频帧
  ctx.drawImage(videoRef.value, 0, 0, canvasRef.value.width, canvasRef.value.height);
  
  // 为每个检测结果绘制框
  detections.forEach(obj => {
    const [x1, y1, x2, y2] = obj.box;
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
    
    // 绘制标签背景
    ctx.fillStyle = '#3b82f6';
    const label = `${obj.class} (${obj.confidence.toFixed(2)})`;
    const textMetrics = ctx.measureText(label);
    ctx.fillRect(x1, y1 - 20, textMetrics.width + 10, 20);
    
    // 绘制标签文本
    ctx.fillStyle = 'white';
    ctx.font = '14px Arial';
    ctx.fillText(label, x1 + 5, y1 - 5);
  });
  debugLog(`已绘制 ${detections.length} 个检测框`);
};

// Export processed video (重组帧为视频)
// 2. 重写视频导出函数，基于时间戳合成视频
const exportProcessedVideo = async () => {
  debugLog("开始导出处理后的视频");
  if (!hasProcessedFrames.value || isExportingVideo.value || processedFrames.value.length === 0) {
    debugLog("无法导出视频: 没有处理过的帧或正在导出中");
    return;
  }
  
  try {
    isExportingVideo.value = true;
    errorMessage.value = '';
    
    const canvas = canvasRef.value;
    const ctx = canvas.getContext('2d');
    const targetFps = 5;
    const frameDuration = 1000 / targetFps; // 每帧显示毫秒数
    
    // 创建视频流和编码器
    const stream = canvas.captureStream(targetFps);
    const videoEncoder = new MediaRecorder(stream, {
      mimeType: 'video/webm; codecs=vp9',
      videoBitsPerSecond: 2500000,
      frameRate: targetFps
    });
    
    const videoChunks = [];
    videoEncoder.ondataavailable = (e) => videoChunks.push(e.data);
    
    // 启动编码器
    videoEncoder.start();
    debugLog("视频编码器已启动");
    
    // 获取原视频时长
    const originalDuration = videoRef.value.duration;
    let lastTimestamp = 0;
    
    // 按时间戳顺序播放所有帧（关键修改）
    for (const frame of processedFrames.value) {
      // 计算当前帧应显示的时间点与上一帧的间隔
      const timeSinceLastFrame = (frame.timestamp - lastTimestamp) * 1000;
      
      // 绘制当前帧
      const img = new Image();
      await new Promise(resolve => {
        img.onload = () => {
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          resolve();
        };
        img.src = frame.dataUrl;
      });
      
      // 等待相应的时间，确保帧显示正确的时长
      await new Promise(resolve => setTimeout(resolve, timeSinceLastFrame));
      lastTimestamp = frame.timestamp;
    }
    
    // 确保视频达到原视频时长
    const finalDelay = Math.max(0, (originalDuration - lastTimestamp) * 1000);
    if (finalDelay > 0) {
      await new Promise(resolve => setTimeout(resolve, finalDelay));
    }
    
    // 完成编码
    await new Promise(resolve => {
      videoEncoder.onstop = resolve;
      videoEncoder.stop();
    });
    
    // 创建下载链接
    const videoBlob = new Blob(videoChunks, { type: 'video/webm' });
    const videoUrl = URL.createObjectURL(videoBlob);
    
    const baseName = selectedVideoName.value ? selectedVideoName.value.replace(/\.[^/.]+$/, "") : "video";
    const a = document.createElement('a');
    a.href = videoUrl;
    a.download = `${baseName}_processed_${originalDuration.toFixed(1)}s_${targetFps}fps.webm`;
    document.body.appendChild(a);
    a.click();
    
    // 清理资源
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(videoUrl);
    }, 100);
    
    debugLog(`视频导出完成，时长应与原视频一致: ${originalDuration.toFixed(2)}秒`);
    
  } catch (err) {
    const errorMsg = `Video export error: ${err.message}`;
    debugLog("视频导出错误", err);
    errorMessage.value = errorMsg;
  } finally {
    isExportingVideo.value = false;
  }
};
    
    

// Reset video and all states
const resetVideo = () => {
  debugLog("开始重置视频和状态");
  // 停止任何检测或处理
  toggleDetection(false);
  
  if (isProcessingFrames.value) {
    debugLog("停止帧处理");
    isProcessingFrames.value = false;
  }
  
  // 停止视频编码器
  if (videoEncoder.value && videoEncoder.value.state !== 'inactive') {
    debugLog("停止视频编码器");
    videoEncoder.value.stop();
  }
  
  // 重置视频
  if (videoRef.value) {
    videoRef.value.pause();
    videoRef.value.src = '';
    debugLog("视频已暂停并清除源");
  }
  
  // 释放资源
  if (videoSource.value) {
    URL.revokeObjectURL(videoSource.value);
    videoSource.value = null;
    debugLog("已释放视频源URL");
  }
  
  // 清除画布
  if (canvasRef.value) {
    const ctx = canvasRef.value.getContext('2d');
    ctx.clearRect(0, 0, canvasRef.value.width, canvasRef.value.height);
    debugLog("已清除canvas");
  }
  
  // 重置状态
  isVideoLoaded.value = false;
  isVideoPlaying.value = false;
  selectedVideoName.value = '';
  detections.value = [];
  allDetections.value = [];
  processedFrames.value = [];
  hasProcessedFrames.value = false;
  currentFrame.value = 0;
  frameProcessingProgress.value = 0;
  videoChunks.value = [];
  errorMessage.value = '';
  debugLog("所有状态已重置");
}

// Export results to XLS
const exportToXLS = async () => {
  debugLog("开始导出结果到XLS");
  if (allDetections.value.length === 0) {
    debugLog("无法导出结果: 没有检测数据");
    return;
  }
  
  try {
    isExporting.value = true;
    debugLog("结果导出已开始，记录数: " + allDetections.value.length);
    
    // Load SheetJS library
    const XLSX = await loadSheetJS();
    
    // Prepare export data
    const exportData = allDetections.value.map((detection, index) => ({
      'Record ID': index + 1,
      'Frame Number': detection.frameNumber,
      'Timestamp': new Date(detection.timestamp).toLocaleString(),
      'Video Time (s)': detection.videoTime.toFixed(2),
      'Class': detection.class,
      'Confidence': detection.confidence.toFixed(4),
      'X1': detection.box[0].toFixed(2),
      'Y1': detection.box[1].toFixed(2),
      'X2': detection.box[2].toFixed(2),
      'Y2': detection.box[3].toFixed(2),
      'Width': (detection.box[2] - detection.box[0]).toFixed(2),
      'Height': (detection.box[3] - detection.box[1]).toFixed(2),
      'Area': ((detection.box[2] - detection.box[0]) * (detection.box[3] - detection.box[1])).toFixed(2)
    }));
    
    // Create workbook and worksheet
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Video_Detections');
    
    // Set column widths
    const wscols = [
      {wch: 8},   // Record ID
      {wch: 12},  // Frame Number
      {wch: 20},  // Timestamp
      {wch: 14},  // Video Time (s)
      {wch: 10},  // Class
      {wch: 12},  // Confidence
      {wch: 10},  // X1
      {wch: 10},  // Y1
      {wch: 10},  // X2
      {wch: 10},  // Y2
      {wch: 10},  // Width
      {wch: 10},  // Height
      {wch: 10}   // Area
    ];
    worksheet['!cols'] = wscols;
    
    // Generate filename
    const baseName = selectedVideoName.value ? selectedVideoName.value.replace(/\.[^/.]+$/, "") : "video";
    const dateStr = new Date().toISOString().slice(0,19).replace(/:/g,'-');
    const fileName = `${baseName}_detections_${dateStr}.xls`;
    
    // Export file
    XLSX.writeFile(workbook, fileName);
    debugLog(`已导出结果文件: ${fileName}`);
    
  } catch (error) {
    debugLog("导出错误", error);
    errorMessage.value = `Export failed: ${error.message}`;
  } finally {
    isExporting.value = false;
    debugLog("结果导出处理完成");
  }
};

// Helper function to format box coordinates
const formatBox = (box) => box.map(coord => coord.toFixed(2)).join(', ');

// Cleanup when component unmounts
onUnmounted(() => {
  debugLog("组件即将卸载，开始清理");
  toggleDetection(false);
  if (videoSource.value) {
    URL.revokeObjectURL(videoSource.value);
  }
  if (videoEncoder.value && videoEncoder.value.state !== 'inactive') {
    videoEncoder.value.stop();
  }
  debugLog("组件清理完成");
});

// Watch for video playing state changes
watch(isVideoPlaying, (newVal) => {
  debugLog(`视频播放状态变化: ${!newVal} -> ${newVal}`);
  // Pause detection when video is paused
  if (!newVal && isDetecting.value) {
    if (detectionInterval.value) {
      clearInterval(detectionInterval.value);
      detectionInterval.value = null;
      debugLog("视频暂停，已停止检测循环");
    }
  }
  
  // Resume detection when video starts playing again
  if (newVal && isDetecting.value && !detectionInterval.value) {
    detectFromVideo();
    detectionInterval.value = setInterval(detectFromVideo, 2000);
    debugLog("视频播放，已恢复检测循环");
  }
});

// Watch for processing mode changes
watch(processingMode, (newMode) => {
  debugLog(`处理模式变化: ${processingMode.value} -> ${newMode}`);
  if (newMode === 'framebyframe') {
    toggleDetection(false);
    pauseVideo();
    debugLog("已切换到逐帧模式，已暂停检测和视频");
  }
});
onMounted(() => {
  debugLog("组件已挂载，检查视频元素是否存在");
  nextTick(() => {
    if (videoRef.value) {
      debugLog("视频元素在组件挂载后存在");
    } else {
      debugLog("警告：组件挂载后视频元素仍不存在");
    }
  });
});
</script>

